namespace App\Jobs;

use App\Models\PatientDossier;
use App\Models\User;
use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;
use Illuminate\Support\Facades\Storage;
use Illuminate\Auth\Access\AuthorizationException;

class PurgePatientDossierJob implements ShouldQueue
{
    use Dispatchable, Queueable;

    public function __construct(public int $dossierId, public int $operatorId)
    {
    }

    public function handle(): void
    {
        $operator = User::findOrFail($this->operatorId);
        $dossier = PatientDossier::findOrFail($this->dossierId);

        if ($operator->hospital_id !== $dossier->hospital_id || !$operator->can('purgeDossier', $dossier)) {
            throw new AuthorizationException('Operator lacks jurisdiction to purge target patient records.');
        }

        Storage::disk('hipaa_archive')->delete($dossier->archive_path);
        $dossier->delete();
    }
}
